"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[746],{718:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-03-gradient-regularization</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-3-градиентный-спуск-обусловленность-и-регуляризация">Лабораторная\nработа 3. Градиентный спуск, обусловленность и регуляризация</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 2</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 2: градиентный спуск (опр. 2.1) и условие сходимости\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn><mo>&lt;</mo><mi>η</mi><mo>&lt;</mo><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">0&lt;\\eta&lt;1/\\lambda_{\\max}</annotation></semantics></math>\n(утв. 2.2), мультиколлинеарность и неустойчивость решения (утв. 2.5),\nгребневая регрессия (опр. 2.7, теорема 2.9), LASSO (опр. 2.12)</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно + домашняя работа (3–4 ч)</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Увидеть, что граница шага из утверждения 2.2 — не запас прочности, а\nточная граница; понять, почему плохая обусловленность делает задачу\nдорогой, а решение неустойчивым; разобраться, что именно делают ridge и\nLASSO и когда они вообще нужны.</p>\n<h2 id="как-устроено-занятие">Как устроено занятие</h2>\n<p>Ноутбук разбирается в аудитории: код запускается и обсуждается по\nходу. Большая часть ячеек уже написана — их нужно <strong>прочитать и\nзапустить</strong>, разобравшись, что происходит и почему.</p>\n<p>Ячейки, помеченные <code># ✍ ЗАДАНИЕ НА СЕМИНАРЕ</code>, заполняются\nсамостоятельно прямо на занятии; их немного, и каждая занимает несколько\nстрок. Ячейки <strong>Вывод</strong> — тоже ваши: короткий ответ своими\nсловами на поставленный вопрос.</p>\n<p>Дома выполняется отдельный ноутбук <code>lab03_homework.ipynb</code>\n— там задания крупнее и делать их нужно самому.</p>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже) — и на семинаре, и в домашней\nработе.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell markdown">\n<blockquote>\n<p><strong>О нормировке.</strong> В §1 лекции 2 функционал берётся без\nусреднения:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">Q(\\theta) = \\|X\\theta - y\\|^2</annotation></semantics></math>,\nпоэтому\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>∇</mi><mi>Q</mi><mo>=</mo><mn>2</mn><msup><mi>X</mi><mi>𝖳</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\nabla Q = 2X^{\\mathsf T}(X\\theta - y)</annotation></semantics></math>\nи граница шага равна\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">1/\\lambda_{\\max}</annotation></semantics></math>.\nЕсли делить на\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>,\nграница изменится в\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>\nраз. <strong>Всегда проверяйте нормировку своего\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math></strong>\n— это самая частая причина «почему у меня градиентный спуск\nразошёлся».</p>\n</blockquote>\n</div>\n<div id="cell002" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> Lasso, LinearRegression, Ridge</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span></code></pre></div>\n</div>\n<div id="cell003" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell004" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">3</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell005" class="cell markdown">\n<hr />\n<h1 id="часть-1-граница-шага--точная">Часть 1. Граница шага —\nточная</h1>\n<p>Определение 2.1:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo>+</mo><mn>1</mn><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>=</mo><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>−</mo><mi>η</mi><mspace width="0.167em"></mspace><mi>∇</mi><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\theta^{(t+1)} = \\theta^{(t)} - \\eta\\,\\nabla Q(\\theta^{(t)})</annotation></semantics></math>.\nУтверждение 2.2 обещает сходимость при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn><mo>&lt;</mo><mi>η</mi><mo>&lt;</mo><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">0 &lt; \\eta &lt; 1/\\lambda_{\\max}</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>λ</mi><mi>max</mi></msub><annotation encoding="application/x-tex">\\lambda_{\\max}</annotation></semantics></math>\n— наибольшее собственное число\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>.</p>\n<p>Идея доказательства подсказывает, что проверять: ошибка в собственном\nбазисе умножается на\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">|</mo><mn>1</mn><mo>−</mo><mn>2</mn><mi>η</mi><msub><mi>λ</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">|</mo></mrow><annotation encoding="application/x-tex">|1 - 2\\eta\\lambda_i|</annotation></semantics></math>.\nПри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>η</mi><mo>=</mo><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">\\eta = 1/\\lambda_{\\max}</annotation></semantics></math>\nмножитель равен ровно единице — то есть граница должна быть\n<strong>точной</strong>, а не с запасом.</p>\n</div>\n<div id="cell006" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> grad_Q(theta, X, y):</span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Градиент Q(theta) = ||X theta - y||^2.</span></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a><span class="co">    Формула выведена в лекции 1, §6: 2 X^T (X theta - y).</span></span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co"> (1 строка)</span></span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span></code></pre></div>\n</div>\n<div id="cell007" class="cell code">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> gradient_descent(X, y, eta, n_iter<span class="op">=</span><span class="dv">120</span>):</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Траектория метода из определения 2.1.&quot;&quot;&quot;</span></span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a>    theta <span class="op">=</span> np.zeros(X.shape[<span class="dv">1</span>])</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a>    traj <span class="op">=</span> [theta.copy()]</span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> _ <span class="kw">in</span> <span class="bu">range</span>(n_iter):</span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a>        theta <span class="op">=</span> theta <span class="op">-</span> eta <span class="op">*</span> grad_Q(theta, X, y)</span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a>        traj.append(theta.copy())</span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> np.array(traj)</span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-11"><a href="#cb4-11" aria-hidden="true" tabindex="-1"></a>n <span class="op">=</span> <span class="dv">200</span></span>\n<span id="cb4-12"><a href="#cb4-12" aria-hidden="true" tabindex="-1"></a>x1 <span class="op">=</span> rng.normal(<span class="dv">0</span>, <span class="dv">1</span>, n)</span>\n<span id="cb4-13"><a href="#cb4-13" aria-hidden="true" tabindex="-1"></a>X_gd <span class="op">=</span> np.column_stack([x1, <span class="fl">0.6</span> <span class="op">*</span> x1 <span class="op">+</span> <span class="fl">0.8</span> <span class="op">*</span> rng.normal(<span class="dv">0</span>, <span class="dv">1</span>, n)])</span>\n<span id="cb4-14"><a href="#cb4-14" aria-hidden="true" tabindex="-1"></a>y_gd <span class="op">=</span> X_gd <span class="op">@</span> np.array([<span class="fl">2.0</span>, <span class="op">-</span><span class="fl">1.0</span>]) <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.5</span>, n)</span>\n<span id="cb4-15"><a href="#cb4-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-16"><a href="#cb4-16" aria-hidden="true" tabindex="-1"></a>theta_star <span class="op">=</span> np.linalg.lstsq(X_gd, y_gd, rcond<span class="op">=</span><span class="va">None</span>)[<span class="dv">0</span>]</span>\n<span id="cb4-17"><a href="#cb4-17" aria-hidden="true" tabindex="-1"></a>lam_max <span class="op">=</span> np.linalg.eigvalsh(X_gd.T <span class="op">@</span> X_gd).<span class="bu">max</span>()</span>\n<span id="cb4-18"><a href="#cb4-18" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;theta* = </span><span class="sc">{</span>np<span class="sc">.</span><span class="bu">round</span>(theta_star, <span class="dv">4</span>)<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb4-19"><a href="#cb4-19" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;lambda_max = </span><span class="sc">{</span>lam_max<span class="sc">:.1f}</span><span class="ss">, граница шага 1/lambda_max = </span><span class="sc">{</span><span class="dv">1</span> <span class="op">/</span> lam_max<span class="sc">:.2e}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell008" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a>Q <span class="op">=</span> <span class="kw">lambda</span> th: np.<span class="bu">sum</span>((X_gd <span class="op">@</span> th <span class="op">-</span> y_gd) <span class="op">**</span> <span class="dv">2</span>)</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a>Q_star <span class="op">=</span> Q(theta_star)</span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots()</span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> c <span class="kw">in</span> [<span class="fl">0.1</span>, <span class="fl">0.5</span>, <span class="fl">0.9</span>, <span class="fl">1.0</span>, <span class="fl">1.05</span>]:</span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a>    gap <span class="op">=</span> np.array([Q(th) <span class="cf">for</span> th <span class="kw">in</span> gradient_descent(X_gd, y_gd, c <span class="op">/</span> lam_max)]) <span class="op">-</span> Q_star</span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a>    ax.semilogy(np.where(np.isfinite(gap) <span class="op">&amp;</span> (gap <span class="op">&gt;</span> <span class="dv">0</span>), gap, np.nan), lw<span class="op">=</span><span class="fl">1.8</span>,</span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a>                label<span class="op">=</span><span class="vs">fr&quot;</span><span class="dv">$</span><span class="er">\\</span><span class="vs">eta = </span><span class="sc">{</span>c<span class="sc">}</span><span class="vs">/</span><span class="er">\\</span><span class="vs">lambda_</span><span class="ch">{{</span><span class="vs">max</span><span class="ch">}}</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a>ax.set_xlabel(<span class="st">&quot;итерация&quot;</span>)<span class="op">;</span> ax.set_ylabel(<span class="vs">r&quot;</span><span class="dv">$</span><span class="vs">Q</span><span class="kw">(</span><span class="ch">\\t</span><span class="vs">heta</span><span class="dv">^</span><span class="vs">{</span><span class="kw">(</span><span class="vs">t</span><span class="kw">)</span><span class="vs">}</span><span class="kw">)</span><span class="vs"> - Q</span><span class="kw">(</span><span class="ch">\\t</span><span class="vs">heta</span><span class="dv">^</span><span class="op">*</span><span class="kw">)</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="st">&quot;Сходимость и граница утверждения 2.2&quot;</span>)<span class="op">;</span> ax.legend()</span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span></code></pre></div>\n</div>\n<div id="cell009" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> При каком множителе спуск перестал сходиться?\nСовпало ли это с границей утверждения 2.2? Как выглядит траектория при\nшаге у самой границы?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell010" class="cell markdown">\n<hr />\n<h1 id="часть-2-цена-плохой-обусловленности">Часть 2. Цена плохой\nобусловленности</h1>\n<p>При оптимальном постоянном шаге ошибка убывает как\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mfrac><mrow><mi>κ</mi><mo>−</mo><mn>1</mn></mrow><mrow><mi>κ</mi><mo>+</mo><mn>1</mn></mrow></mfrac><msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mi>t</mi></msup></mrow><annotation encoding="application/x-tex">\\bigl(\\frac{\\kappa-1}{\\kappa+1}\\bigr)^t</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>κ</mi><mo>=</mo><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msub><mi>λ</mi><mi>max</mi></msub><mi>/</mi><msub><mi>λ</mi><mi>min</mi></msub></mrow><annotation encoding="application/x-tex">\\kappa = \\mathrm{cond}(X^{\\mathsf T}X) = \\lambda_{\\max}/\\lambda_{\\min}</annotation></semantics></math>.\nЗначит, число итераций до заданной точности растёт <strong>линейно по\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>κ</mi><annotation encoding="application/x-tex">\\kappa</annotation></semantics></math></strong>.</p>\n</div>\n<div id="cell011" class="cell code">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> design_with_cond(n_obj, p, kappa, generator):</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Матрица X с заданным cond(X^T X) = kappa.&quot;&quot;&quot;</span></span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a>    A <span class="op">=</span> generator.normal(size<span class="op">=</span>(n_obj, p))</span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a>    U, _, Vt <span class="op">=</span> np.linalg.svd(A, full_matrices<span class="op">=</span><span class="va">False</span>)</span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> U <span class="op">@</span> np.diag(np.logspace(<span class="dv">0</span>, <span class="op">-</span><span class="fl">0.5</span> <span class="op">*</span> np.log10(kappa), p)) <span class="op">@</span> Vt</span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> iters_to_converge(X, y, tol<span class="op">=</span><span class="fl">1e-6</span>, max_iter<span class="op">=</span><span class="dv">400_000</span>):</span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a>    ev <span class="op">=</span> np.linalg.eigvalsh(X.T <span class="op">@</span> X)</span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a>    eta <span class="op">=</span> <span class="fl">1.0</span> <span class="op">/</span> (ev.<span class="bu">max</span>() <span class="op">+</span> ev.<span class="bu">min</span>())              <span class="co"># оптимальный постоянный шаг</span></span>\n<span id="cb6-11"><a href="#cb6-11" aria-hidden="true" tabindex="-1"></a>    opt <span class="op">=</span> np.linalg.lstsq(X, y, rcond<span class="op">=</span><span class="va">None</span>)[<span class="dv">0</span>]</span>\n<span id="cb6-12"><a href="#cb6-12" aria-hidden="true" tabindex="-1"></a>    theta <span class="op">=</span> np.zeros(X.shape[<span class="dv">1</span>])</span>\n<span id="cb6-13"><a href="#cb6-13" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> t <span class="kw">in</span> <span class="bu">range</span>(<span class="dv">1</span>, max_iter <span class="op">+</span> <span class="dv">1</span>):</span>\n<span id="cb6-14"><a href="#cb6-14" aria-hidden="true" tabindex="-1"></a>        theta <span class="op">=</span> theta <span class="op">-</span> eta <span class="op">*</span> grad_Q(theta, X, y)</span>\n<span id="cb6-15"><a href="#cb6-15" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> np.linalg.norm(theta <span class="op">-</span> opt) <span class="op">&lt;</span> tol <span class="op">*</span> np.linalg.norm(opt):</span>\n<span id="cb6-16"><a href="#cb6-16" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> t</span>\n<span id="cb6-17"><a href="#cb6-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> np.nan</span></code></pre></div>\n</div>\n<div id="cell012" class="cell code">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>gen <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> kappa <span class="kw">in</span> np.logspace(<span class="dv">1</span>, <span class="fl">4.5</span>, <span class="dv">8</span>):</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a>    Xk <span class="op">=</span> design_with_cond(<span class="dv">300</span>, <span class="dv">8</span>, kappa, gen)</span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a>    yk <span class="op">=</span> Xk <span class="op">@</span> gen.normal(size<span class="op">=</span><span class="dv">8</span>) <span class="op">+</span> gen.normal(<span class="dv">0</span>, <span class="fl">0.01</span>, <span class="dv">300</span>)</span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a>    rows.append({<span class="st">&quot;kappa&quot;</span>: np.linalg.cond(Xk.T <span class="op">@</span> Xk), <span class="st">&quot;итераций&quot;</span>: iters_to_converge(Xk, yk)})</span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a>tab <span class="op">=</span> pd.DataFrame(rows)</span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots()</span>\n<span id="cb7-10"><a href="#cb7-10" aria-hidden="true" tabindex="-1"></a>ax.loglog(tab[<span class="st">&quot;kappa&quot;</span>], tab[<span class="st">&quot;итераций&quot;</span>], <span class="st">&quot;o-&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;эксперимент&quot;</span>)</span>\n<span id="cb7-11"><a href="#cb7-11" aria-hidden="true" tabindex="-1"></a>ax.loglog(tab[<span class="st">&quot;kappa&quot;</span>], tab[<span class="st">&quot;kappa&quot;</span>] <span class="op">*</span> np.log(<span class="fl">1e6</span>) <span class="op">/</span> <span class="dv">2</span>, <span class="st">&quot;k--&quot;</span>, label<span class="op">=</span><span class="vs">r&quot;</span><span class="dv">$</span><span class="er">\\</span><span class="vs">propto </span><span class="er">\\</span><span class="vs">kappa</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb7-12"><a href="#cb7-12" aria-hidden="true" tabindex="-1"></a>ax.set_xlabel(<span class="vs">r&quot;</span><span class="dv">$</span><span class="er">\\</span><span class="vs">kappa = </span><span class="dv">\\m</span><span class="vs">athrm{cond}</span><span class="kw">(</span><span class="vs">X</span><span class="dv">^</span><span class="vs">{</span><span class="dv">\\m</span><span class="vs">athsf{T}}X</span><span class="kw">)</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb7-13"><a href="#cb7-13" aria-hidden="true" tabindex="-1"></a>ax.set_ylabel(<span class="vs">r&quot;итераций до </span><span class="dv">$</span><span class="vs">10</span><span class="dv">^</span><span class="vs">{-6}</span><span class="dv">$</span><span class="vs">&quot;</span>)<span class="op">;</span> ax.legend()</span>\n<span id="cb7-14"><a href="#cb7-14" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="st">&quot;Цена плохой обусловленности&quot;</span>)</span>\n<span id="cb7-15"><a href="#cb7-15" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span>\n<span id="cb7-16"><a href="#cb7-16" aria-hidden="true" tabindex="-1"></a>display(tab.<span class="bu">round</span>(<span class="dv">0</span>))</span></code></pre></div>\n</div>\n<div id="cell013" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Как число итераций зависит от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>κ</mi><annotation encoding="application/x-tex">\\kappa</annotation></semantics></math>?\nЧто это означает для признаков, измеренных в разных единицах?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell014" class="cell markdown">\n<hr />\n<h1 id="часть-3-мультиколлинеарность-решение-перестаёт-быть-определённым">Часть\n3. Мультиколлинеарность: решение перестаёт быть определённым</h1>\n<p>Признаки мультиколлинеарны, если столбцы\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>X</mi><annotation encoding="application/x-tex">X</annotation></semantics></math>\nпочти линейно зависимы. Тогда у\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>\nесть собственное число, близкое к нулю, и по утверждению 2.5 малое\nвозмущение данных даёт большое изменение решения:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mrow><mo stretchy="false" form="postfix">∥</mo><mi>δ</mi><mi>θ</mi><mo stretchy="false" form="postfix">∥</mo></mrow><mrow><mo stretchy="false" form="postfix">∥</mo><mi>θ</mi><mo stretchy="false" form="postfix">∥</mo></mrow></mfrac><mo>≤</mo><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo stretchy="false" form="postfix">)</mo><mspace width="0.167em"></mspace><mfrac><mrow><mo stretchy="false" form="postfix">∥</mo><mi>δ</mi><mi>b</mi><mo stretchy="false" form="postfix">∥</mo></mrow><mrow><mo stretchy="false" form="postfix">∥</mo><mi>b</mi><mo stretchy="false" form="postfix">∥</mo></mrow></mfrac><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\frac{\\|\\delta\\theta\\|}{\\|\\theta\\|} \\le \\mathrm{cond}(X^{\\mathsf T}X)\\,\n\\frac{\\|\\delta b\\|}{\\|b\\|}.\n</annotation></semantics></math></p>\n<p>Посмотрим на это не через оценку, а напрямую: обучим модель на 300\nбутстреп-выборках и нарисуем облако полученных решений.</p>\n</div>\n<div id="cell015" class="cell code">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a>rho <span class="op">=</span> <span class="fl">0.992</span>                                   <span class="co"># корреляция признаков</span></span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>z <span class="op">=</span> rng.normal(size<span class="op">=</span><span class="dv">200</span>)</span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a>X_col <span class="op">=</span> np.column_stack([z, rho <span class="op">*</span> z <span class="op">+</span> np.sqrt(<span class="dv">1</span> <span class="op">-</span> rho <span class="op">**</span> <span class="dv">2</span>) <span class="op">*</span> rng.normal(size<span class="op">=</span><span class="dv">200</span>)])</span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a>y_col <span class="op">=</span> X_col <span class="op">@</span> np.array([<span class="fl">1.0</span>, <span class="fl">1.0</span>]) <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.3</span>, <span class="dv">200</span>)</span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;корреляция признаков: </span><span class="sc">{</span>np<span class="sc">.</span>corrcoef(X_col.T)[<span class="dv">0</span>, <span class="dv">1</span>]<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;cond(X^T X) = </span><span class="sc">{</span>np<span class="sc">.</span>linalg<span class="sc">.</span>cond(X_col.T <span class="op">@</span> X_col)<span class="sc">:.1f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;МНК-решение = </span><span class="sc">{</span>np<span class="sc">.</span><span class="bu">round</span>(np.linalg.lstsq(X_col, y_col, rcond<span class="op">=</span><span class="va">None</span>)[<span class="dv">0</span>], <span class="dv">3</span>)<span class="sc">}</span><span class="ss">&quot;</span></span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a>      <span class="ss">f&quot;   (истина [1. 1.])&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell016" class="cell code">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a>boots <span class="op">=</span> np.array([np.linalg.lstsq(X_col[idx], y_col[idx], rcond<span class="op">=</span><span class="va">None</span>)[<span class="dv">0</span>]</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a>                  <span class="cf">for</span> idx <span class="kw">in</span> (rng.integers(<span class="dv">0</span>, <span class="dv">200</span>, <span class="dv">200</span>) <span class="cf">for</span> _ <span class="kw">in</span> <span class="bu">range</span>(<span class="dv">300</span>))])</span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a>fig, ax <span class="op">=</span> plt.subplots(figsize<span class="op">=</span>(<span class="fl">5.5</span>, <span class="dv">5</span>))</span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a>ax.scatter(boots[:, <span class="dv">0</span>], boots[:, <span class="dv">1</span>], s<span class="op">=</span><span class="dv">10</span>, alpha<span class="op">=</span><span class="fl">0.4</span>, color<span class="op">=</span><span class="st">&quot;#128C7E&quot;</span>)</span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a>ax.plot(<span class="dv">1</span>, <span class="dv">1</span>, <span class="st">&quot;*&quot;</span>, ms<span class="op">=</span><span class="dv">16</span>, color<span class="op">=</span><span class="st">&quot;black&quot;</span>, label<span class="op">=</span><span class="st">&quot;истина&quot;</span>)</span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a>ax.set_xlabel(<span class="vs">r&quot;</span><span class="dv">$</span><span class="ch">\\t</span><span class="vs">heta_1</span><span class="dv">$</span><span class="vs">&quot;</span>)<span class="op">;</span> ax.set_ylabel(<span class="vs">r&quot;</span><span class="dv">$</span><span class="ch">\\t</span><span class="vs">heta_2</span><span class="dv">$</span><span class="vs">&quot;</span>)<span class="op">;</span> ax.legend()</span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a>ax.set_title(<span class="vs">fr&quot;300 бутстреп-оценок при </span><span class="dv">$</span><span class="ch">\\r</span><span class="vs">ho = </span><span class="sc">{</span>rho<span class="sc">}</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-11"><a href="#cb9-11" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;ст. отклонение theta_1:              </span><span class="sc">{</span>boots[:, <span class="dv">0</span>]<span class="sc">.</span>std()<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb9-12"><a href="#cb9-12" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;ст. отклонение суммы theta_1+theta_2: </span><span class="sc">{</span>boots<span class="sc">.</span><span class="bu">sum</span>(axis<span class="op">=</span><span class="dv">1</span>)<span class="sc">.</span>std()<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb9-13"><a href="#cb9-13" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;корреляция оценок:                   </span><span class="sc">{</span>np<span class="sc">.</span>corrcoef(boots.T)[<span class="dv">0</span>, <span class="dv">1</span>]<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell017" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Вдоль какого направления вытянуто облако и\nпочему? Какая величина оценивается устойчиво, а какая — нет?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell018" class="cell markdown">\n<hr />\n<h1 id="часть-4-ridge-и-lasso-что-они-делают-с-решением">Часть 4. Ridge\nи LASSO: что они делают с решением</h1>\n<p>Определение 2.7 и теорема 2.9: гребневая регрессия минимизирует\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>+</mo><mi>λ</mi><msub><mo>∑</mo><mrow><mi>j</mi><mo>≥</mo><mn>1</mn></mrow></msub><msubsup><mi>θ</mi><mi>j</mi><mn>2</mn></msubsup></mrow><annotation encoding="application/x-tex">\\|X\\theta-y\\|^2 + \\lambda\\sum_{j\\ge1}\\theta_j^2</annotation></semantics></math>,\nи решение равно\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo>+</mo><mi>λ</mi><mi>D</mi><msup><mo stretchy="false" form="postfix">)</mo><mrow><mi>−</mi><mn>1</mn></mrow></msup><msup><mi>X</mi><mi>𝖳</mi></msup><mi>y</mi></mrow><annotation encoding="application/x-tex">(X^{\\mathsf T}X + \\lambda D)^{-1}X^{\\mathsf T}y</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>D</mi><annotation encoding="application/x-tex">D</annotation></semantics></math>\nне штрафует свободный член. Матрица\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo>+</mo><mi>λ</mi><mi>D</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X+\\lambda D</annotation></semantics></math>\nположительно определена при любом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\lambda&gt;0</annotation></semantics></math>\n— <strong>даже если\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>\nвырождена</strong>.</p>\n<p>LASSO (опр. 2.12) штрафует\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>∑</mo><mo stretchy="false" form="prefix">|</mo><msub><mi>θ</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">|</mo></mrow><annotation encoding="application/x-tex">\\sum|\\theta_j|</annotation></semantics></math>.\nЯвной формулы нет, но поведение качественно иное: решение становится\n<strong>разреженным</strong>. Посмотрим на регуляризационные пути.</p>\n</div>\n<div id="cell019" class="cell code">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Разреженная задача: из 12 признаков полезны ровно три</span></span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a>n_obj <span class="op">=</span> <span class="dv">120</span></span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a>X_sp <span class="op">=</span> rng.normal(size<span class="op">=</span>(n_obj, <span class="dv">12</span>))</span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a>theta_sparse <span class="op">=</span> np.zeros(<span class="dv">12</span>)<span class="op">;</span> theta_sparse[[<span class="dv">0</span>, <span class="dv">3</span>, <span class="dv">7</span>]] <span class="op">=</span> [<span class="fl">3.0</span>, <span class="op">-</span><span class="fl">2.0</span>, <span class="fl">1.5</span>]</span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a>y_sp <span class="op">=</span> X_sp <span class="op">@</span> theta_sparse <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.3</span>, n_obj)</span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a>alphas <span class="op">=</span> np.logspace(<span class="op">-</span><span class="dv">3</span>, <span class="fl">1.2</span>, <span class="dv">60</span>)</span>\n<span id="cb10-8"><a href="#cb10-8" aria-hidden="true" tabindex="-1"></a>path_ridge <span class="op">=</span> np.array([Ridge(alpha<span class="op">=</span>a).fit(X_sp, y_sp).coef_ <span class="cf">for</span> a <span class="kw">in</span> alphas])</span>\n<span id="cb10-9"><a href="#cb10-9" aria-hidden="true" tabindex="-1"></a>path_lasso <span class="op">=</span> np.array([Lasso(alpha<span class="op">=</span>a, max_iter<span class="op">=</span><span class="dv">50_000</span>).fit(X_sp, y_sp).coef_</span>\n<span id="cb10-10"><a href="#cb10-10" aria-hidden="true" tabindex="-1"></a>                       <span class="cf">for</span> a <span class="kw">in</span> alphas])</span></code></pre></div>\n</div>\n<div id="cell020" class="cell code">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">3</span>, figsize<span class="op">=</span>(<span class="dv">15</span>, <span class="dv">4</span>))</span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> ax, path, name <span class="kw">in</span> [(axes[<span class="dv">0</span>], path_ridge, <span class="st">&quot;Ridge ($L_2$)&quot;</span>),</span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a>                       (axes[<span class="dv">1</span>], path_lasso, <span class="st">&quot;LASSO ($L_1$)&quot;</span>)]:</span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> j <span class="kw">in</span> <span class="bu">range</span>(<span class="dv">12</span>):</span>\n<span id="cb11-5"><a href="#cb11-5" aria-hidden="true" tabindex="-1"></a>        useful <span class="op">=</span> j <span class="kw">in</span> (<span class="dv">0</span>, <span class="dv">3</span>, <span class="dv">7</span>)</span>\n<span id="cb11-6"><a href="#cb11-6" aria-hidden="true" tabindex="-1"></a>        ax.plot(alphas, path[:, j], lw<span class="op">=</span><span class="fl">2.2</span> <span class="cf">if</span> useful <span class="cf">else</span> <span class="fl">1.0</span>,</span>\n<span id="cb11-7"><a href="#cb11-7" aria-hidden="true" tabindex="-1"></a>                color<span class="op">=</span><span class="va">None</span> <span class="cf">if</span> useful <span class="cf">else</span> <span class="st">&quot;grey&quot;</span>, alpha<span class="op">=</span><span class="fl">1.0</span> <span class="cf">if</span> useful <span class="cf">else</span> <span class="fl">0.5</span>)</span>\n<span id="cb11-8"><a href="#cb11-8" aria-hidden="true" tabindex="-1"></a>    ax.set_xscale(<span class="st">&quot;log&quot;</span>)<span class="op">;</span> ax.axhline(<span class="dv">0</span>, color<span class="op">=</span><span class="st">&quot;black&quot;</span>, lw<span class="op">=</span><span class="fl">0.8</span>)</span>\n<span id="cb11-9"><a href="#cb11-9" aria-hidden="true" tabindex="-1"></a>    ax.set_xlabel(<span class="vs">r&quot;</span><span class="dv">$</span><span class="ch">\\a</span><span class="vs">lpha</span><span class="dv">$</span><span class="vs">&quot;</span>)<span class="op">;</span> ax.set_ylabel(<span class="vs">r&quot;</span><span class="dv">$</span><span class="ch">\\t</span><span class="vs">heta_j</span><span class="dv">$</span><span class="vs">&quot;</span>)<span class="op">;</span> ax.set_title(name)</span>\n<span id="cb11-10"><a href="#cb11-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-11"><a href="#cb11-11" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].semilogx(alphas, (np.<span class="bu">abs</span>(path_ridge) <span class="op">&gt;</span> <span class="fl">1e-8</span>).<span class="bu">sum</span>(axis<span class="op">=</span><span class="dv">1</span>), lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;Ridge&quot;</span>)</span>\n<span id="cb11-12"><a href="#cb11-12" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].semilogx(alphas, (np.<span class="bu">abs</span>(path_lasso) <span class="op">&gt;</span> <span class="fl">1e-8</span>).<span class="bu">sum</span>(axis<span class="op">=</span><span class="dv">1</span>), lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;LASSO&quot;</span>)</span>\n<span id="cb11-13"><a href="#cb11-13" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].axhline(<span class="dv">3</span>, ls<span class="op">=</span><span class="st">&quot;--&quot;</span>, color<span class="op">=</span><span class="st">&quot;black&quot;</span>, label<span class="op">=</span><span class="st">&quot;истинное число ненулевых&quot;</span>)</span>\n<span id="cb11-14"><a href="#cb11-14" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].set_xlabel(<span class="vs">r&quot;</span><span class="dv">$</span><span class="ch">\\a</span><span class="vs">lpha</span><span class="dv">$</span><span class="vs">&quot;</span>)<span class="op">;</span> axes[<span class="dv">2</span>].set_ylabel(<span class="st">&quot;ненулевых коэффициентов&quot;</span>)</span>\n<span id="cb11-15"><a href="#cb11-15" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">2</span>].set_title(<span class="st">&quot;Разреженность&quot;</span>)<span class="op">;</span> axes[<span class="dv">2</span>].legend()</span>\n<span id="cb11-16"><a href="#cb11-16" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()<span class="op">;</span> plt.show()</span>\n<span id="cb11-17"><a href="#cb11-17" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;серым — признаки, истинный коэффициент которых равен нулю&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell021" class="cell markdown">\n<h3 id="задание-41-геометрия-почему-l_1-обнуляет">Задание 4.1.\nГеометрия: почему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>L</mi><mn>1</mn></msub><annotation encoding="application/x-tex">L_1</annotation></semantics></math>\nобнуляет</h3>\n<p>Линии уровня\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>\n— эллипсы. Рост\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>λ</mi><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math>\nравносилен поиску минимума\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>\nна множестве\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">{</mo><mo stretchy="false" form="postfix">∥</mo><mi>θ</mi><msub><mo stretchy="false" form="postfix">∥</mo><mn>1</mn></msub><mo>≤</mo><mi>c</mi><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">\\{\\|\\theta\\|_1 \\le c\\}</annotation></semantics></math>\n(ромб) или\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">{</mo><mo stretchy="false" form="postfix">∥</mo><mi>θ</mi><msub><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msub><mo>≤</mo><mi>c</mi><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">\\{\\|\\theta\\|_2 \\le c\\}</annotation></semantics></math>\n(круг). Найдите этот минимум перебором точек границы и посмотрите, куда\nон попадает.</p>\n</div>\n<div id="cell022" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a>Xg <span class="op">=</span> np.array([[<span class="fl">1.0</span>, <span class="fl">0.35</span>], [<span class="fl">0.35</span>, <span class="fl">1.0</span>], [<span class="fl">0.5</span>, <span class="fl">0.7</span>]])</span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a>yg <span class="op">=</span> np.array([<span class="fl">1.4</span>, <span class="fl">0.6</span>, <span class="fl">1.0</span>])</span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a>Qg <span class="op">=</span> <span class="kw">lambda</span> t: np.<span class="bu">sum</span>((Xg <span class="op">@</span> t <span class="op">-</span> yg) <span class="op">**</span> <span class="dv">2</span>)</span>\n<span id="cb12-6"><a href="#cb12-6" aria-hidden="true" tabindex="-1"></a>c <span class="op">=</span> <span class="fl">0.6</span></span>\n<span id="cb12-7"><a href="#cb12-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-8"><a href="#cb12-8" aria-hidden="true" tabindex="-1"></a>ts <span class="op">=</span> np.linspace(<span class="dv">0</span>, <span class="dv">1</span>, <span class="dv">2001</span>)</span>\n<span id="cb12-9"><a href="#cb12-9" aria-hidden="true" tabindex="-1"></a>border_l1 <span class="op">=</span> np.vstack([np.column_stack([c <span class="op">*</span> (<span class="dv">1</span> <span class="op">-</span> ts), c <span class="op">*</span> ts]),</span>\n<span id="cb12-10"><a href="#cb12-10" aria-hidden="true" tabindex="-1"></a>                       np.column_stack([<span class="op">-</span>c <span class="op">*</span> ts, c <span class="op">*</span> (<span class="dv">1</span> <span class="op">-</span> ts)]),</span>\n<span id="cb12-11"><a href="#cb12-11" aria-hidden="true" tabindex="-1"></a>                       np.column_stack([<span class="op">-</span>c <span class="op">*</span> (<span class="dv">1</span> <span class="op">-</span> ts), <span class="op">-</span>c <span class="op">*</span> ts]),</span>\n<span id="cb12-12"><a href="#cb12-12" aria-hidden="true" tabindex="-1"></a>                       np.column_stack([c <span class="op">*</span> ts, <span class="op">-</span>c <span class="op">*</span> (<span class="dv">1</span> <span class="op">-</span> ts)])])</span>\n<span id="cb12-13"><a href="#cb12-13" aria-hidden="true" tabindex="-1"></a>phi <span class="op">=</span> np.linspace(<span class="dv">0</span>, <span class="dv">2</span> <span class="op">*</span> np.pi, <span class="dv">4001</span>)</span>\n<span id="cb12-14"><a href="#cb12-14" aria-hidden="true" tabindex="-1"></a>border_l2 <span class="op">=</span> np.column_stack([c <span class="op">*</span> np.cos(phi), c <span class="op">*</span> np.sin(phi)])</span>\n<span id="cb12-15"><a href="#cb12-15" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-16"><a href="#cb12-16" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co"> (2-3 строки): для каждой границы найдите точку с минимальным Qg</span></span>\n<span id="cb12-17"><a href="#cb12-17" aria-hidden="true" tabindex="-1"></a><span class="co">#                    и напечатайте её координаты.</span></span></code></pre></div>\n</div>\n<div id="cell023" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Куда попал минимум для ромба и куда — для\nкруга? Почему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>L</mi><mn>1</mn></msub><annotation encoding="application/x-tex">L_1</annotation></semantics></math>\nобнуляет координаты, а\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>L</mi><mn>2</mn></msub><annotation encoding="application/x-tex">L_2</annotation></semantics></math>\n— нет?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell024" class="cell markdown">\n<hr />\n<h1 id="часть-5-когда-регуляризация-вообще-нужна">Часть 5. Когда\nрегуляризация вообще нужна</h1>\n<p>Часто пропускаемый вопрос. Проверим на индивидуальной выборке в двух\nрежимах: как есть и после расширения признакового пространства до\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo>&gt;</mo><mi>ℓ</mi></mrow><annotation encoding="application/x-tex">p &gt; \\ell</annotation></semantics></math>.</p>\n</div>\n<div id="cell025" class="cell code">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> PolynomialFeatures, StandardScaler</span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant)</span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a>Xtr_full, Xte <span class="op">=</span> data[<span class="st">&quot;X_train&quot;</span>], data[<span class="st">&quot;X_test&quot;</span>]</span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a>ytr_full, yte <span class="op">=</span> data[<span class="st">&quot;y_train&quot;</span>], data[<span class="st">&quot;y_test&quot;</span>]</span>\n<span id="cb13-7"><a href="#cb13-7" aria-hidden="true" tabindex="-1"></a>mse <span class="op">=</span> <span class="kw">lambda</span> pred: np.mean((pred <span class="op">-</span> yte) <span class="op">**</span> <span class="dv">2</span>)</span>\n<span id="cb13-8"><a href="#cb13-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-9"><a href="#cb13-9" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;объектов </span><span class="sc">{</span>Xtr_full<span class="sc">.</span>shape[<span class="dv">0</span>]<span class="sc">}</span><span class="ss">, признаков </span><span class="sc">{</span>Xtr_full<span class="sc">.</span>shape[<span class="dv">1</span>]<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb13-10"><a href="#cb13-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;МНК:       MSE = </span><span class="sc">{</span>mse(LinearRegression().fit(Xtr_full, ytr_full).predict(Xte))<span class="sc">:.4g}</span><span class="ss">&quot;</span>)</span>\n<span id="cb13-11"><a href="#cb13-11" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;Ridge(1):  MSE = </span><span class="sc">{</span>mse(Ridge(alpha<span class="op">=</span><span class="fl">1.0</span>).fit(Xtr_full, ytr_full).predict(Xte))<span class="sc">:.4g}</span><span class="ss">&quot;</span>)</span>\n<span id="cb13-12"><a href="#cb13-12" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;константа: MSE = </span><span class="sc">{</span>mse(ytr_full.mean())<span class="sc">:.4g}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell026" class="cell code">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Теперь p &gt; l: полиномиальное расширение и урезанная обучающая выборка</span></span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a>poly, scaler <span class="op">=</span> PolynomialFeatures(degree<span class="op">=</span><span class="dv">2</span>, include_bias<span class="op">=</span><span class="va">False</span>), StandardScaler()</span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a>Xs_tr <span class="op">=</span> scaler.fit_transform(poly.fit_transform(Xtr_full[:<span class="dv">120</span>]))</span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a>Xs_te <span class="op">=</span> scaler.transform(poly.transform(Xte))</span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a>ys_tr <span class="op">=</span> ytr_full[:<span class="dv">120</span>]</span>\n<span id="cb14-6"><a href="#cb14-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;объектов </span><span class="sc">{</span>Xs_tr<span class="sc">.</span>shape[<span class="dv">0</span>]<span class="sc">}</span><span class="ss">, признаков </span><span class="sc">{</span>Xs_tr<span class="sc">.</span>shape[<span class="dv">1</span>]<span class="sc">}</span><span class="ss"> -&gt; p &gt; l&quot;</span>)</span>\n<span id="cb14-7"><a href="#cb14-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-8"><a href="#cb14-8" aria-hidden="true" tabindex="-1"></a>Xa, Xv, ya, yv <span class="op">=</span> train_test_split(Xs_tr, ys_tr, test_size<span class="op">=</span><span class="fl">0.3</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb14-9"><a href="#cb14-9" aria-hidden="true" tabindex="-1"></a>alpha_max <span class="op">=</span> np.<span class="bu">abs</span>(Xa.T <span class="op">@</span> (ya <span class="op">-</span> ya.mean())).<span class="bu">max</span>() <span class="op">/</span> <span class="bu">len</span>(ya)</span>\n<span id="cb14-10"><a href="#cb14-10" aria-hidden="true" tabindex="-1"></a>grid <span class="op">=</span> np.logspace(np.log10(alpha_max) <span class="op">-</span> <span class="dv">4</span>, np.log10(alpha_max), <span class="dv">30</span>)</span></code></pre></div>\n</div>\n<div id="cell027" class="cell markdown">\n<h3 id="задание-51-подбор-alpha-по-отложенной-части">Задание 5.1. Подбор\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>α</mi><annotation encoding="application/x-tex">\\alpha</annotation></semantics></math>\nпо отложенной части</h3>\n<p>Контрольную выборку трогать нельзя — она нужна для финальной оценки.\nПоэтому\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>α</mi><annotation encoding="application/x-tex">\\alpha</annotation></semantics></math>\nподбираем по отложенной части обучающей. Полноценный скользящий контроль\nбудет на занятии 5.</p>\n</div>\n<div id="cell028" class="cell code" data-tags="[&quot;task&quot;,&quot;exercise&quot;]">\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="co"># ✍ ЗАДАНИЕ НА СЕМИНАРЕ — допишите эту ячейку</span></span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a>rows <span class="op">=</span> []</span>\n<span id="cb15-4"><a href="#cb15-4" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> name, Model <span class="kw">in</span> [(<span class="st">&quot;Ridge&quot;</span>, Ridge), (<span class="st">&quot;LASSO&quot;</span>, Lasso)]:</span>\n<span id="cb15-5"><a href="#cb15-5" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co"> (3-4 строки): по сетке grid обучите Model(alpha=a) на (Xa, ya),</span></span>\n<span id="cb15-6"><a href="#cb15-6" aria-hidden="true" tabindex="-1"></a>    <span class="co">#   выберите a_best по MSE на (Xv, yv), переобучите на всей (Xs_tr, ys_tr),</span></span>\n<span id="cb15-7"><a href="#cb15-7" aria-hidden="true" tabindex="-1"></a>    <span class="co">#   запишите MSE на контроле и число ненулевых коэффициентов.</span></span>\n<span id="cb15-8"><a href="#cb15-8" aria-hidden="true" tabindex="-1"></a>    ...</span>\n<span id="cb15-9"><a href="#cb15-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-10"><a href="#cb15-10" aria-hidden="true" tabindex="-1"></a>theta_ols <span class="op">=</span> np.linalg.lstsq(Xs_tr, ys_tr <span class="op">-</span> ys_tr.mean(), rcond<span class="op">=</span><span class="va">None</span>)[<span class="dv">0</span>]</span>\n<span id="cb15-11"><a href="#cb15-11" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;МНК:       MSE = </span><span class="sc">{</span>mse(Xs_te <span class="op">@</span> theta_ols <span class="op">+</span> ys_tr.mean())<span class="sc">:.4g}</span><span class="ss">&quot;</span>)</span>\n<span id="cb15-12"><a href="#cb15-12" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;константа: MSE = </span><span class="sc">{</span>mse(ys_tr.mean())<span class="sc">:.4g}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell029" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> В каком из двух режимов регуляризация дала\nвыигрыш и почему? Сформулируйте правило, когда она нужна.</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell030" class="cell markdown">\n<h2 id="итоги-занятия">Итоги занятия</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Утверждение 2.2 требует\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>η</mi><mo>&lt;</mo><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">\\eta &lt; 1/\\lambda_{\\max}</annotation></semantics></math>.\nКак изменится граница, если минимизировать усреднённый функционал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\frac1\\ell\\|X\\theta-y\\|^2</annotation></semantics></math>?</li>\n<li>Два признака имеют корреляцию 0.999. Что произойдёт с оценками их\nкоэффициентов и с их суммой? Какая величина оценивается устойчиво?</li>\n<li>Почему в определении 2.7 свободный член не штрафуется? Что\nпроизойдёт с решением, если прибавить ко всем\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>y</mi><mi>i</mi></msub><annotation encoding="application/x-tex">y_i</annotation></semantics></math>\nконстанту 1000, а\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>θ</mi><mn>0</mn></msub><annotation encoding="application/x-tex">\\theta_0</annotation></semantics></math>\nпри этом штрафовать?</li>\n<li>Ridge и LASSO дали одинаковое качество. Какой выберете и почему?\nПриведите по одному аргументу за каждый.</li>\n</ol>\n<hr />\n<p><strong>Дома:</strong> откройте <code>lab03_homework.ipynb</code> —\nтам три задачи: свой SGD с расписаниями шага, LASSO покоординатным\nспуском и байесовский взгляд на регуляризацию.</p>\n</div>\n</body>\n</html>\n'}}]);